From da496cb80c75c8d948998b0b94ff70673ac14160 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 19:31:08 +0100
Subject: [PATCH] panel config: add an option to copy the panel to new screens

Setting up the same panel on every screen meant cloning it by hand each
time a new screen was connected. The panel settings now have a checkbox
to add a copy of the panel to newly connected screens without panels.

BUG: 497100
---
 .../configuration/PanelConfiguration.qml      | 20 ++++++++++++++++++-
 1 file changed, 19 insertions(+), 1 deletion(-)

diff --git a/desktoppackage/contents/configuration/PanelConfiguration.qml b/desktoppackage/contents/configuration/PanelConfiguration.qml
index cb897a1f04..725332adb2 100644
--- a/desktoppackage/contents/configuration/PanelConfiguration.qml
+++ b/desktoppackage/contents/configuration/PanelConfiguration.qml
@@ -624,7 +624,7 @@ ColumnLayout {
         Layout.alignment: Qt.AlignHCenter
         rowSpacing: Kirigami.Units.largeSpacing
         columnSpacing: Kirigami.Units.largeSpacing
-        rows: 2
+        rows: 3
         columns: 2

         PC3.Label {
@@ -684,6 +684,24 @@ ColumnLayout {
                 plasmoid.globalShortcut = button.keySequence
             }
         }
+
+        PC3.Label {
+            Layout.alignment: Qt.AlignRight
+            text: i18ndc("plasma_shell_org.kde.plasma.desktop", "@label:checkbox", "New screens:")
+            textFormat: Text.PlainText
+        }
+        RowLayout {
+            spacing: Kirigami.Units.smallSpacing
+
+            PC3.CheckBox {
+                text: i18ndc("plasma_shell_org.kde.plasma.desktop", "@option:check", "Add a copy of this panel")
+                checked: panel.cloneToNewScreens
+                onToggled: panel.cloneToNewScreens = checked
+            }
+            PlasmaExtras.ContextualHelpButton {
+                toolTipText: i18ndc("plasma_shell_org.kde.plasma.desktop", "@info:tooltip", "When a screen without any panels is connected, a copy of this panel is added to it. Later changes to this panel are not applied to the copies.")
+            }
+        }
     }

     PlasmaExtras.PlasmoidHeading {
-- 
