Subject: [PATCH] shell: optionally add a copy of a panel to newly connected
 screens

Setting up the same panel on every screen meant cloning it by hand each
time a new screen was connected. Panels now have an option to copy
themselves to any newly connected screen that doesn't have panels yet.

BUG: 497100
---
 shell/panelview.cpp   | 21 +++++++++++++++
 shell/panelview.h     | 10 +++++++
 shell/shellcorona.cpp | 61 +++++++++++++++++++++++++++++++++++++++++++
 shell/shellcorona.h   |  1 +
 4 files changed, 93 insertions(+)

diff --git a/shell/panelview.cpp b/shell/panelview.cpp
index 5c0ac43e71..42d0bc490c 100644
--- a/shell/panelview.cpp
+++ b/shell/panelview.cpp
@@ -54,6 +54,7 @@ PanelView::PanelView(ShellCorona *corona, QScreen *targetScreen, QWindow *parent
     , m_initCompleted(false)
     , m_floating(false)
     , m_floatingApplets(false)
+    , m_cloneToNewScreens(false)
     , m_alignment(Qt::AlignCenter)
     , m_corona(corona)
     , m_visibilityMode(NormalPanel)
@@ -400,6 +401,25 @@ void PanelView::setFloatingApplets(bool floatingApplets)
     Q_EMIT floatingAppletsChanged();
 }

+bool PanelView::cloneToNewScreens() const
+{
+    return m_cloneToNewScreens;
+}
+
+void PanelView::setCloneToNewScreens(bool clone)
+{
+    if (m_cloneToNewScreens == clone) {
+        return;
+    }
+
+    m_cloneToNewScreens = clone;
+    if (hasConfig()) {
+        resolutionIndependentConfig().writeEntry("cloneToNewScreens", clone);
+        m_corona->requestApplicationConfigSync();
+    }
+    Q_EMIT cloneToNewScreensChanged();
+}
+
 int PanelView::minThickness() const
 {
     if (formFactor() == Plasma::Types::Vertical) {
@@ -848,6 +868,7 @@ void PanelView::restore()

     setFloating((bool)resolutionIndependentConfig().readEntry<int>("floating", defaultFloating()));
     setFloatingApplets((bool)resolutionIndependentConfig().readEntry<int>("floatingApplets", false));
+    setCloneToNewScreens(resolutionIndependentConfig().readEntry("cloneToNewScreens", false));
     setThickness(configDefaults().readEntry("thickness", m_configuredThickness));

