--- a/shell/shellcorona.cpp
+++ b/shell/shellcorona.cpp
@@ -1455,9 +1455,11 @@ void ShellCorona::handleScreenOrderChanged(QList<QScreen *> screens)
     }

     // Second: add everything that wasn't there yet
+    QList<QScreen *> newScreens;
     for (auto *s : screens) {
         if (!desktopForScreen(s)) {
             addOutput(s);
+            newScreens << s;
         }
     }

@@ -1471,9 +1473,67 @@ void ShellCorona::handleScreenOrderChanged(QList<QScreen *> screens)
         Q_EMIT availableScreenRegionChanged(i);
     }

+    for (auto *s : std::as_const(newScreens)) {
+        clonePanelsToNewScreen(s);
+    }
+
     CHECK_SCREEN_INVARIANTS
 }

+void ShellCorona::clonePanelsToNewScreen(QScreen *screen)
+{
+    const auto screenId = m_screenPool->idForScreen(screen);
+    DesktopView *desktopView = desktopForScreen(screen);
+    if (!screenId.has_value() || !desktopView) {
+        return;
+    }
+
+    // A screen that already has panels, even ones still waiting for their view, keeps them
+    const auto allContainments = containments();
+    const bool hasPanels = std::ranges::any_of(allContainments, [&screenId](Plasma::Containment *cont) {
+        return (cont->containmentType() == Plasma::Containment::Panel || cont->containmentType() == Plasma::Containment::CustomPanel) && !cont->destroyed()
+            && cont->screen() == screenId.value();
+    });
+    if (hasPanels) {
+        return;
+    }
+
+    QList<QPointer<PanelView>> panelsToClone;
+    for (PanelView *panel : std::as_const(m_panelViews)) {
+        if (panel->cloneToNewScreens() && panel->screenToFollow() != screen) {
+            panelsToClone << panel;
+        }
+    }
+    if (panelsToClone.isEmpty()) {
+        return;
+    }
+
+    auto clonePanels = [this, screen = QPointer(screen), panelsToClone]() {
+        if (!screen) {
+            return;
+        }
+        for (const auto &panel : panelsToClone) {
+            if (panel && panel->containment()) {
+                clonePanelTo(panel, panel->location(), screen);
+            }
+        }
+    };
+
+    // The cloned panels can only get a view once the new desktop is ready
+    Plasma::Containment *desktop = desktopView->containment();
+    if (desktop->isUiReady()) {
+        clonePanels();
+    } else {
+        auto connection = std::make_shared<QMetaObject::Connection>();
+        *connection = connect(desktop, &Plasma::Containment::uiReadyChanged, this, [connection, clonePanels](bool ready) {
+            if (ready) {
+                QObject::disconnect(*connection);
+                clonePanels();
+            }
+        });
+    }
+}
+
 void ShellCorona::addOutput(QScreen *screen)
 {
     Q_ASSERT(screen);
@@ -2533,6 +2593,7 @@ void ShellCorona::clonePanelTo(PanelView *oldPanelView, Plasma::Types::Location
         KConfigGroup targetViewConfig = targetPanelView->resolutionIndependentConfig();

         viewConfig.copyTo(&targetViewConfig);
+        targetViewConfig.deleteEntry("cloneToNewScreens");

         if (wantedScreen) {
             targetPanelView->setScreenToFollow(wantedScreen);
